code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Full 2-lines remain visible through the grid; the 3 rings overwrite
    # some cells on the line where each marker sits.
    horizontal = [r for r in range(h) if sum(v == 2 for v in grid[r]) >= w // 2]
    vertical = [c for c in range(w) if sum(grid[r][c] == 2 for r in range(h)) >= h // 2]

    centers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(grid[rr][cc] == 3
                    for rr, cc in ((r-1,c-1),(r-1,c),(r-1,c+1),
                                   (r,c-1),(r,c+1),
                                   (r+1,c-1),(r+1,c),(r+1,c+1))):
                centers.append((r, c))

    beams = []
    for r, c in centers:
        if c in vertical:
            beams.append(('row', r))
        if r in horizontal:
            beams.append(('col', c))

    # Extend each marker from its 2-line across the grid, preserving existing
    # markers and 2-line cells.
    for axis, pos in beams:
        if axis == 'row':
            for c in range(w):
                if out[pos][c] == 0:
                    out[pos][c] = 1
        else:
            for r in range(h):
                if out[r][pos] == 0:
                    out[r][pos] = 1

    # At each crossing of a beam and another parallel 2-line, make a 1 frame
    # around the 2 at the crossing.
    for axis, pos in beams:
        crossings = horizontal if axis == 'col' else vertical
        for cross in crossings:
            cr, cc = (cross, pos) if axis == 'col' else (pos, cross)
            if grid[cr][cc] != 2:
                continue
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    rr, cc2 = cr + dr, cc + dc
                    if (0 <= rr < h and 0 <= cc2 < w and
                            (dr != 0 or dc != 0) and out[rr][cc2] != 3):
                        out[rr][cc2] = 1
    return out
'''
